def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_pressure = 0
    urgent_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 120:
                rich_pressure += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opponents += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return min(budget, 40.0)
        return min(budget, 12.0)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0
    if hp <= 2:
        danger += 2
    elif hp <= 4:
        danger += 1
    if no_water_days >= 1:
        danger += 2

    if danger >= 3:
        base = max(78.0, highest_prev + 3.0)
    elif danger == 2:
        base = max(62.0, avg_prev * 0.72 + 6.0)
    elif danger == 1:
        base = max(42.0, avg_prev * 0.45)
    else:
        base = 24.0 + scarcity * 18.0

    if supply <= 17:
        base += 18.0
    elif supply >= 22:
        base -= 8.0

    base += rich_pressure * 4.0
    base += urgent_opponents * 2.0

    if highest_prev >= 160:
        if danger == 0 and supply >= 20:
            base = min(base, 34.0)
        else:
            base = max(base, 74.0)
    elif highest_prev >= 130:
        if danger == 0 and supply >= 21:
            base = min(base, 30.0)
        else:
            base = max(base, 58.0)

    remaining_days = max(1, 10 - day + 1)
    reserve_target = remaining_days * 18.0
    affordable = max(0.0, budget - reserve_target)

    if danger == 0:
        bid = min(base, max(22.0, affordable))
    elif danger == 1:
        bid = min(base, max(35.0, affordable + 10.0))
    else:
        bid = min(base, max(55.0, affordable + 20.0))

    if budget < 35:
        bid = min(bid, budget)
    else:
        bid = min(bid, budget, 95.0)

    if hp <= 2 and budget > 0:
        bid = max(bid, min(budget, 82.0))
    if no_water_days >= 1 and budget > 0:
        bid = max(bid, min(budget, 76.0))

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

