def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    num_water_units = int(day_context['supply'] / WATER_REQ)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Base bid logic
    bid = DAILY_SALARY * 0.7 # Moderate base

    if my_status['hp'] <= 2: # Critical HP
        bid = DAILY_SALARY * 1.15 # Very aggressive, potentially above salary
    elif my_status['hp'] <= 4: # Low HP
        bid = DAILY_SALARY * 1.0 # Aggressive
    elif my_status['hp'] >= 8 and len(alive_opponents) > num_water_units: # Good HP, high competition
        bid = DAILY_SALARY * 0.85 # Slightly higher base
    elif my_status['hp'] >= 8 and len(alive_opponents) <= num_water_units: # Good HP, low competition
        bid = DAILY_SALARY * 0.6 # Conserve more

    # Adjust bid based on yesterday's highest bid and competition
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if len(alive_opponents) > num_water_units: # High competition
            if highest_prev_bid >= DAILY_SALARY * 0.9:
                bid = max(bid, highest_prev_bid + 5) # Try to outbid strong competitors
            else:
                bid = max(bid, highest_prev_bid + 2) # Maintain strong presence
        else: # Lower competition
            if highest_prev_bid >= DAILY_SALARY * 0.9 and my_status['hp'] > 4:
                bid = max(bid, DAILY_SALARY * 0.8) # Still bid reasonably, but avoid overspending if HP is good
            else:
                bid = max(bid, highest_prev_bid * 0.9) # Bid slightly below or match

    return min(my_status['budget'], bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    # handle potential float supply for index, not used here
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # default aggressive bid
    desired_bid = DAILY_SALARY * 0.7  # 56

    if yesterday_bids:
        max_last = max(yesterday_bids)
        # If we are at risk, outbid the highest previous by a margin
        if hp <= 2 or no_water >= 1:
            desired_bid = max(max_last + 1.0, DAILY_SALARY * 0.85)
        else:
            # try to undercut slightly if we have high HP
            if hp > 4:
                desired_bid = max(max_last - 2.0, DAILY_SALARY * 0.5)
            else:
                desired_bid = max(max_last + 0.5, DAILY_SALARY * 0.6)
    else:
        # no history, bid conservatively
        desired_bid = DAILY_SALARY * 0.5  # 40

    # enforce budget and minimal sensible bid
    final_bid = min(budget, max(desired_bid, 1.0))
    return final_bid
